q=json.loads((P/'questions.json').read_text());seen={x['parent'] for x in q}
for line in raw.splitlines():
 parent,question,*rest=line.split('|');assert len(rest)==6
 if parent in seen:continue
 answer=[int(x) for x in rest[4].split(',')]
 q.append(dict(id=f'Q-{len(q)+1:03}',parent=parent,type='multiple' if len(answer)>1 else 'single',question=question,options=rest[:4],answer=answer,explanation=rest[5],origin='自编训练题，非官方真题'));seen.add(parent)
(P/'questions.json').write_text(json.dumps(q,ensure_ascii=False,indent=2));print(len(q),'questions covering',len(seen),'models')
